(*----- Function qcp_assert -----*)

Definition qcp_assert_safety_wit_1 := 
forall (c_pre: Z) ,
  ((( &( "c" ) )) # Int  |-> c_pre)
|--
  “ (0 <= INT_MAX) ” 
  &&  “ ((INT_MIN) <= 0) ”
.

Definition qcp_assert_entail_wit_1 := 
  TT && emp 
|--
  TT && emp 
.

Definition qcp_assert_entail_wit_2 := 
forall (c_pre: Z) (PreH1 : (c_pre = 0)) ,
  TT && emp 
|--
  TT && emp 
.

Definition qcp_assert_return_wit_1 := 
forall (c_pre: Z) (PreH1 : (c_pre <> 0)) ,
  TT && emp 
|--
  “ (c_pre <> 0) ”
  &&  emp
.

